// === Tab: mySketch ===
var ants = [],
	col = [],
	mode = 2,
	rows, columns, factor = 1;

function setup() {
	createCanvas(windowWidth, windowHeight);
	makeAnts(1);
	col[0] = color(0);
	col[1] = color(255);
	strokeWeight(1);
}

function draw() {
	var ratio,
		i, j, colNr;
	if (dist(ants[0][0].x, ants[0][0].y, ants[0][1].x, ants[0][1].y) > 1) {
		ratio = 0.05 + 0.02 * mode;
		for (i = 0; i < ants.length; i++) {
			colNr = mode > 0 ? frameCount % 2 : (i + frameCount) % 2;
			fill(col[colNr]);
			stroke(col[colNr]);
			drawPolygon(ants[i]);
		}

		for (i = 0; i < ants.length; i++) {
			if (i % 2 == 0 && mode > 0) {
				for (j = 0; j < ants[i].length; j++) {
					ants[i][j].x = ants[i][j].x + ratio * (ants[i][(j + 1) % ants[i].length].x - ants[i][j].x);
					ants[i][j].y = ants[i][j].y + ratio * (ants[i][(j + 1) % ants[i].length].y - ants[i][j].y);
				}
			} else {
				for (j = 0; j < ants[i].length; j++) {
					ants[i][j].x = ants[i][j].x + ratio * (ants[i][j > 0 ? j - 1 : ants[i].length - 1].x - ants[i][j].x);
					ants[i][j].y = ants[i][j].y + ratio * (ants[i][j > 0 ? j - 1 : ants[i].length - 1].y - ants[i][j].y);
				}
			}
		}

	}
}

function makeAnts() {
	var r, i, j,
		ang = 0,
		maxX, maxAng, x, y, deltaX, deltaY;
	background(100);
	ants.length = 0;
	r = 0.25 * max(width, height);
	if (mode == 0) {
		maxAng = 3;
		deltaX = (r + r * cos(PI / 3)) * 0.5 * factor;
		deltaY = 2 * r * sin(PI / 3) * factor;
	} else if (mode == 1) {
		maxAng = 4;
		deltaX = sqrt(2) * r * factor;
		deltaY = sqrt(2) * r * factor;
	} else {
		maxAng = 6;
		deltaX = 1.5 * r * factor;
		deltaY = 2 * r * sin(PI / 3) * factor;
	}
	columns = floor(width / deltaX) + 5;
	rows = floor(height / deltaY) + 5;
	x = -2 * deltaX;
	y = -2 * deltaY;
	for (i = 0; i < rows * columns; i++) {
		ants[i] = [];
		for (j = 0; j < maxAng; j++) {
			if (mode == 0) {
				ants[i][j] = {
					x: x + r * cos(ang + PI / 3 * ((i % columns) % 2)) + (r * factor * cos(PI / 3) - deltaX) * ((i % columns) % 2),
					y: y + r * sin(ang + PI / 3 * ((i % columns) % 2)) + r * factor * sin(PI / 3) * ((i % columns) % 2)
				}
			} else if (mode == 1) {
				ants[i][j] = {
					x: x + r * cos(ang + PI / 4),
					y: y + r * sin(ang + PI / 4)
				}
			} else {
				ants[i][j] = {
					x: x + r * cos(ang + PI / 3),
					y: y + r * sin(ang + PI / 3) - r * factor * sin(PI / 3) * ((i % columns) % 2)
				}
			}
			ang += 2 * PI / maxAng;
		}
		x += deltaX;
		if (i % columns == 0 && i > 0) {
			ang = 0;
			x = -2 * deltaX;
			y += deltaY;
		}
	}
}

function drawPolygon(vertices) {
	beginShape();
	for (var i = 0; i < vertices.length; i++) {
		vertex(vertices[i].x, vertices[i].y);
	}
	vertex(vertices[0].x, vertices[0].y);
	endShape();
}

function mouseClicked() {
	factor = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), width / 2, height / 2) / width * 4 + 0.1;
	makeAnts();
}

function keyPressed() {
	if (key == '3' || key == '4' || key == '6') {
		if (key == '3') {
			mode = 0;
		} else if (key == '4') {
			mode = 1;
		} else {
			mode = 2;
		}
		factor = 1;
		makeAnts();
	}
}
